using UnityEngine;

namespace Game.UI
{
    /// <summary>
    /// What the credits screen shows, in order: sections of string-table keys, then the full licence texts that must ship
    /// with the assets they cover (the SIL Open Font License of the fonts). Generated by <c>Tools/Generate/Credits</c>;
    /// the source list with sources and licences is <c>Docs/LICENCES.md</c>.
    /// </summary>
    [CreateAssetMenu(menuName = "Game/Credits", fileName = "Credits")]
    public sealed class CreditsDefinition : ScriptableObject
    {
        [SerializeField] private string _titleKey = "credits.title";
        [SerializeField] private CreditsSection[] _sections = new CreditsSection[0];
        [SerializeField] private string _licencesTitleKey = "credits.section.licences";
        [Tooltip("Shown word for word at the end (legal text, not translated).")]
        [SerializeField] private TextAsset[] _licenceTexts = new TextAsset[0];

        public string TitleKey => _titleKey;

        public CreditsSection[] Sections => _sections;

        public string LicencesTitleKey => _licencesTitleKey;

        public TextAsset[] LicenceTexts => _licenceTexts;

        public void Set(CreditsSection[] sections, TextAsset[] licenceTexts)
        {
            _sections = sections ?? new CreditsSection[0];
            _licenceTexts = licenceTexts ?? new TextAsset[0];
        }

        private void OnValidate()
        {
            for (int i = 0; i < _sections.Length; i++)
            {
                if (_sections[i] == null || string.IsNullOrEmpty(_sections[i].TitleKey))
                {
                    Debug.LogWarning($"{name}: credits section {i} has no title key.", this);
                }
            }

            for (int i = 0; i < _licenceTexts.Length; i++)
            {
                if (_licenceTexts[i] == null)
                {
                    Debug.LogWarning($"{name}: licence text {i} is missing.", this);
                }
            }
        }
    }
}
